"""Persist fixed subjective judgments and exact-ID count-only deferrals."""
import collections,hashlib,json,pathlib,sqlite3
R=pathlib.Path(__file__).resolve().parents[2];D=R/'data/sft-readiness-v3'
assert not(R/'runs/STOP').exists() and not(D/'STOP').exists()
s=json.loads((D/'quality-selection.json').read_text());assert hashlib.sha256((D/'quality-samples.jsonl').read_bytes()).hexdigest()==s['sample_sha256'];assert hashlib.sha256((D/'custody.json').read_bytes()).hexdigest()==s['custody_sha256']
r=[json.loads(l) for l in (D/'quality-samples.jsonl').read_text().splitlines()]
review={3:'Overconfident mechanics explanation at final turn; requires subject review, not externally fact-checked.',4:'Unqualified first-computer claims and museum-location assertion require fact checking.',7:'Speculative dream-journal benefit, albeit with qualified direct-sleep claim.',8:'Blanket easy-on-joints claim and generic beginner exercise prescription warrant review.',17:'Rewrite adds specific economic claims not supplied by user, although request permits improvement.',19:'Broad unverified model self-capability claims should not be transferred as established capability.',22:'Role-play invents a specific driver excuse not supplied in the prior turn; fictional role is explicit.',24:'Carousel-lathe identification and explanation warrant domain verification; not externally fact-checked.',30:'Key-point selection emphasizes dinner over planned paper submission; arguable task-focus mismatch.',36:'Historical update-date identity should not become this own-base model self-description.',41:'Friendly rewrite weakens demand for immediate remediation and project-risk emphasis.',44:'Friendly rewrite drops explicit consequence of repeated delay, altering a substantive main point.'}
hold={9:'Guarantees accurate/relevant AI output without basis.',12:'Unresolved relation/count placeholders; invents meeting outcomes with no supplied facts.',16:'Fabricates article contents although referenced article is absent.',26:'Uses He despite explicit system prohibition of third-person pronouns.',28:'Uses She despite explicit system prohibition of third-person pronouns.',31:'Five sentences exceed system maximum3; misassigns buy-back clause to loan rather than permanent deal; third-person pronoun also present.',32:'Five sentences exceed explicit system maximum3 and adds editorial conclusion.',46:'Changes already-held meeting to upcoming and invents positive effort/feedback narrative.'}
judgments=[]
for i,x in enumerate(r,1):
 judgments.append({k:x[k] for k in ('doc_id','source','quartile','input_tokens','target_tokens')}|{'sample_number':i,'rating':'hold' if i in hold else 'review' if i in review else 'retain','reason':hold.get(i,review.get(i,'Coherent task-appropriate response; no material issue noticed in this limited review.'))})
assert len(judgments)==48
(D/'quality-judgments.json').write_text(json.dumps(judgments,indent=2)+'\n')
defer={x['doc_id'] for x in judgments if x['rating']!='retain'};ex=set(json.loads((D/'custody.json').read_text())['excluded_doc_ids']);con=sqlite3.connect(f'file:{D}/candidates.sqlite?mode=ro',uri=True);counts=collections.defaultdict(collections.Counter)
for did,source,split,targets in con.execute('select doc_id,source,split,target_tokens from documents'):
 if did in ex:continue
 c=counts[source+':'+split];c['before_documents']+=1;c['before_targets']+=targets
 if did in defer:c['deferred_documents']+=1;c['deferred_targets']+=targets
 else:c['remaining_documents']+=1;c['remaining_targets']+=targets
result={'state':'subjective_review_complete_not_admitted','training_admitted':False,'ratings':{source:dict(collections.Counter(j['rating'] for j in judgments if j['source']==source)) for source in sorted({j['source'] for j in judgments})},'counts':dict(counts),'proposed_excluded_doc_ids':sorted(defer),'selection_sha256':hashlib.sha256((D/'quality-selection.json').read_bytes()).hexdigest(),'judgments_sha256':hashlib.sha256((D/'quality-judgments.json').read_bytes()).hexdigest(),'limitations':['Exact sample deferrals only; unreviewed analogues are not repaired.','Subjective AI judgment, not statistical certification or external fact-checking.','Pre-host-policy transformation; systems and reply reservations require later revalidation.']}
(D/'quality-review.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
